/**
 * Core shared primitive types used by the engine, the server and the client.
 * Keep this file dependency-free.
 */

export const GRID_SIZE = 10;

export type Slot = 0 | 1;

export interface Coord {
	row: number;
	col: number;
}

export type Orientation = 'horizontal' | 'vertical';

export type ItemId = 'firewall' | 'database' | 'backup' | 'server' | 'iot-cluster' | 'router';

/** A single item placement as submitted by a client (or generated by the server). */
export interface Placement {
	item: ItemId;
	row: number;
	col: number;
	orientation: Orientation;
}

/** Engine phases. 'lobby' only exists at the room level (waiting for the 2nd player). */
export type EnginePhase = 'placement' | 'battle' | 'game-over';
export type Phase = 'lobby' | EnginePhase;

export type Difficulty = 'easy' | 'medium' | 'hard';
export const DIFFICULTIES: readonly Difficulty[] = ['easy', 'medium', 'hard'] as const;

/** Fixed whitelist of quick emotes (no free text chat, prevents abuse). */
export const EMOTES = ['gg', 'glhf', 'nice', 'oops', 'wow', 'thinking', 'taunt', 'thanks'] as const;
export type EmoteId = (typeof EMOTES)[number];

/** Display text for emotes (client-side rendering; never sent as free text). */
export const EMOTE_TEXT: Record<EmoteId, string> = {
	gg: 'GG',
	glhf: 'GL HF',
	nice: 'Nice shot!',
	oops: 'Oops...',
	wow: 'Wow!',
	thinking: 'Hmm...',
	taunt: 'Your firewall is made of paper.',
	thanks: 'Thanks!'
};

export function otherSlot(slot: Slot): Slot {
	return slot === 0 ? 1 : 0;
}

export function coordKey(c: Coord): string {
	return `${c.row},${c.col}`;
}

export function sameCoord(a: Coord, b: Coord): boolean {
	return a.row === b.row && a.col === b.col;
}

export function inBounds(c: Coord, size: number = GRID_SIZE): boolean {
	return (
		Number.isInteger(c.row) &&
		Number.isInteger(c.col) &&
		c.row >= 0 &&
		c.col >= 0 &&
		c.row < size &&
		c.col < size
	);
}

/** Orthogonal neighbours (in bounds). */
export function neighbors4(c: Coord, size: number = GRID_SIZE): Coord[] {
	return [
		{ row: c.row - 1, col: c.col },
		{ row: c.row + 1, col: c.col },
		{ row: c.row, col: c.col - 1 },
		{ row: c.row, col: c.col + 1 }
	].filter((n) => inBounds(n, size));
}

/** All 8 surrounding neighbours (in bounds). */
export function neighbors8(c: Coord, size: number = GRID_SIZE): Coord[] {
	const out: Coord[] = [];
	for (let dr = -1; dr <= 1; dr++) {
		for (let dc = -1; dc <= 1; dc++) {
			if (dr === 0 && dc === 0) continue;
			const n = { row: c.row + dr, col: c.col + dc };
			if (inBounds(n, size)) out.push(n);
		}
	}
	return out;
}
